     1→# ABOUTME: IR builder for transforming parsed Chalk code into Sea of Nodes IR
     2→# ABOUTME: Provides methods called by semantic actions to build IR nodes during parsing
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Builder {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→    use Chalk::IR::Scope;
    11→
    12→    # Phase 1 polymorphic node classes
    13→    use Chalk::IR::Node::Base;
    14→    use Chalk::IR::Node::Constant;
    15→    use Chalk::IR::Node::Start;
    16→    use Chalk::IR::Node::Return;
    17→    use Chalk::IR::Node::Add;
    18→    use Chalk::IR::Node::Subtract;
    19→    use Chalk::IR::Node::Multiply;
    20→    use Chalk::IR::Node::Divide;
    21→    use Chalk::IR::Node::Negate;
    22→    use Chalk::IR::Node::GT;
    23→    use Chalk::IR::Node::LT;
    24→    use Chalk::IR::Node::EQ;
    25→    use Chalk::IR::Node::NE;
    26→    use Chalk::IR::Node::LE;
    27→    use Chalk::IR::Node::GE;
    28→    use Chalk::IR::Node::If;
    29→    use Chalk::IR::Node::Proj;
    30→    use Chalk::IR::Node::Region;
    31→    use Chalk::IR::Node::Phi;
    32→    use Chalk::IR::Node::Loop;
    33→
    34→    field $graph :reader;
    35→    field $scope :reader;
    36→    field $node_counter :reader = 0;
    37→    field $current_control :reader;  # Current control flow node
    38→    field $loop_entry_scope;  # Snapshot of scope bindings at loop entry
    39→    field $loop_tracking_active = 0;  # Whether loop tracking is active
    40→
    41→    ADJUST {
    42→        $graph = Chalk::IR::Graph->new();
    43→        $scope = Chalk::IR::Scope->new();
    44→    }
    45→
    46→    # Generate unique node ID
    47→    method next_node_id() {
    48→        my $id = "node_$node_counter";
    49→        $node_counter++;
    50→        return $id;
    51→    }
    52→
    53→    # Set current control flow node
    54→    method set_control($ctrl) {
    55→        $current_control = $ctrl;
    56→    }
    57→
    58→    # Create Start node for a function/method
    59→    method build_start_node($function_name = 'main', $params = undef) {
    60→        $params //= [];
    61→        my $node_id = $self->next_node_id();
    62→        my $empty_inputs = [];
    63→        my $start = Chalk::IR::Node::Start->new(
    64→            id            => $node_id,
    65→            inputs        => $empty_inputs,
    66→            function_name => $function_name,
    67→            params        => $params,
    68→        );
    69→        $graph->add_node($start);
    70→        $self->set_control($start->id);
    71→
    72→        # Create Proj nodes for each parameter and register in scope
    73→        my $param_count = scalar($params->@*);
    74→        for my $i (0..($param_count - 1)) {
    75→            my $param_name = $params->[$i];
    76→            my $proj = $self->build_proj_node($start, $i, $param_name);
    77→            # Register parameter Proj in scope so lookups return it directly
    78→            $scope->define($param_name, $proj->id);
    79→        }
    80→
    81→        return $start;
    82→    }
    83→
    84→    # Create Constant node
    85→    method build_constant_node($value, $type = 'Int') {
    86→        my $node_id = $self->next_node_id();
    87→        my $constant = Chalk::IR::Node::Constant->new(
    88→            id            => $node_id,
    89→            inputs        => [$current_control],
    90→            value         => $value,
    91→            type          => $type,
    92→        );
    93→        $graph->add_node($constant);
    94→        return $constant;
    95→    }
    96→
    97→    # Create Return node
    98→    # If $control is undef, uses current_control. Otherwise uses provided control.
    99→    method build_return_node($value_node, $control = undef) {
   100→        # Debug: check what we received
   101→        my $ref_type = ref($value_node) || 'SCALAR';
   102→        my $prefix = substr($ref_type, 0, 15);
   103→        my $is_node = ($prefix eq 'Chalk::IR::Node') ? 1 : 0;
   104→        unless ($ref_type && $is_node) {
   105→            warn "build_return_node received non-node: $ref_type\n";
   106→            return undef;
   107→        }
   108→
   109→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
   110→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
   111→
   112→        my $node_id = $self->next_node_id();
   113→        my $return = Chalk::IR::Node::Return->new(
   114→            id            => $node_id,
   115→            inputs        => [$ctrl, $value_node->id],
   116→            value_id      => $value_node->id,
   117→            control_id    => $ctrl,
   118→        );
   119→        $graph->add_node($return);
   120→        return $return;
   121→    }
   122→
   123→    # Set control input for an existing node
   124→    method set_node_control($node, $control_id) {
   125→        my $inputs = $node->inputs;
   126→        $inputs->[0] = $control_id;  # Control is always first input
   127→    }
   128→
   129→    # Create arithmetic operation nodes
   130→    method build_add_node($left_node, $right_node) {
   131→        my $node_id = $self->next_node_id();
   132→        my $add = Chalk::IR::Node::Add->new(
   133→            id => $node_id,
   134→            inputs => [$current_control, $left_node->id, $right_node->id],
   135→            left_id => $left_node->id,
   136→            right_id => $right_node->id,
   137→        );
   138→        $graph->add_node($add);
   139→        return $add;
   140→    }
   141→
   142→    method build_multiply_node($left_node, $right_node) {
   143→        my $node_id = $self->next_node_id();
   144→        my $mul = Chalk::IR::Node::Multiply->new(
   145→            id => $node_id,
   146→            inputs => [$current_control, $left_node->id, $right_node->id],
   147→            left_id => $left_node->id,
   148→            right_id => $right_node->id,
   149→        );
   150→        $graph->add_node($mul);
   151→        return $mul;
   152→    }
   153→
   154→    method build_sub_node($left_node, $right_node) {
   155→        my $node_id = $self->next_node_id();
   156→        my $sub = Chalk::IR::Node::Subtract->new(
   157→            id => $node_id,
   158→            inputs => [$current_control, $left_node->id, $right_node->id],
   159→            left_id => $left_node->id,
   160→            right_id => $right_node->id,
   161→        );
   162→        $graph->add_node($sub);
   163→        return $sub;
   164→    }
   165→
   166→    method build_divide_node($left_node, $right_node) {
   167→        my $node_id = $self->next_node_id();
   168→        my $div = Chalk::IR::Node::Divide->new(
   169→            id => $node_id,
   170→            inputs => [$current_control, $left_node->id, $right_node->id],
   171→            left_id => $left_node->id,
   172→            right_id => $right_node->id,
   173→        );
   174→        $graph->add_node($div);
   175→        return $div;
   176→    }
   177→
   178→    # Create Store node (variable assignment)
   179→    method build_store_node($var_name, $value_node, $control = undef) {
   180→        # Use provided control, or current_control, or '__CONTROL_PLACEHOLDER__'
   181→        my $ctrl = $control // $current_control // '__CONTROL_PLACEHOLDER__';
   182→
   183→        my $value_ref = { op => 'NodeRef', node_id => $value_node->id };
   184→        my $attributes = {
   185→            name => $var_name,
   186→            value => $value_ref
   187→        };
   188→        my $node_id = $self->next_node_id();
   189→        my $store = Chalk::IR::Node->new(
   190→            id            => $node_id,
   191→            op            => 'Store',
   192→            inputs        => [$ctrl, $value_node->id],
   193→            attributes    => $attributes,
   194→        );
   195→        $graph->add_node($store);
   196→        $scope->define($var_name, $store->id);
   197→        return $store;
   198→    }
   199→
   200→    # Create Load node (variable read)
   201→    method build_load_node($var_name) {
   202→        my $node_id = $scope->lookup($var_name);
   203→        return undef unless $node_id;
   204→
   205→        # Check if this is a Proj node (parameter) - if so, return it directly
   206→        my $node = $graph->nodes->{$node_id};
   207→        if ($node && $node->op eq 'Proj') {
   208→            # Parameter: return the Proj node directly
   209→            return $node;
   210→        }
   211→
   212→        # Regular variable: create Load node from Store
   213→        my $attributes = {
   214→            name => $var_name,
   215→            store_id => $node_id
   216→        };
   217→        my $load_id = $self->next_node_id();
   218→        my $load = Chalk::IR::Node->new(
   219→            id            => $load_id,
   220→            op            => 'Load',
   221→            inputs        => [$current_control, $node_id],
   222→            attributes    => $attributes,
   223→        );
   224→        $graph->add_node($load);
   225→        return $load;
   226→    }
   227→
   228→    # Create Proj node (projection from MultiNode like Start)
   229→    method build_proj_node($source_node, $index, $label) {
   230→        my $node_id = $self->next_node_id();
   231→        my $proj = Chalk::IR::Node::Proj->new(
   232→            id            => $node_id,
   233→            inputs        => [$source_node->id],
   234→            index         => $index,
   235→            label         => $label,
   236→        );
   237→        $graph->add_node($proj);
   238→        return $proj;
   239→    }
   240→
   241→    # Comparison nodes
   242→    method build_greater_node($left_node, $right_node) {
   243→        my $node_id = $self->next_node_id();
   244→        my $cmp = Chalk::IR::Node::GT->new(
   245→            id            => $node_id,
   246→            inputs        => [$current_control, $left_node->id, $right_node->id],
   247→            left_id       => $left_node->id,
   248→            right_id      => $right_node->id,
   249→        );
   250→        $graph->add_node($cmp);
   251→        return $cmp;
   252→    }
   253→
   254→    method build_less_node($left_node, $right_node) {
   255→        my $node_id = $self->next_node_id();
   256→        my $cmp = Chalk::IR::Node::LT->new(
   257→            id            => $node_id,
   258→            inputs        => [$current_control, $left_node->id, $right_node->id],
   259→            left_id       => $left_node->id,
   260→            right_id      => $right_node->id,
   261→        );
   262→        $graph->add_node($cmp);
   263→        return $cmp;
   264→    }
   265→
   266→    method build_equal_node($left_node, $right_node) {
   267→        my $node_id = $self->next_node_id();
   268→        my $cmp = Chalk::IR::Node::EQ->new(
   269→            id            => $node_id,
   270→            inputs        => [$current_control, $left_node->id, $right_node->id],
   271→            left_id       => $left_node->id,
   272→            right_id      => $right_node->id,
   273→        );
   274→        $graph->add_node($cmp);
   275→        return $cmp;
   276→    }
   277→
   278→    method build_greater_or_equal_node($left_node, $right_node) {
   279→        my $node_id = $self->next_node_id();
   280→        my $cmp = Chalk::IR::Node::GE->new(
   281→            id            => $node_id,
   282→            inputs        => [$current_control, $left_node->id, $right_node->id],
   283→            left_id       => $left_node->id,
   284→            right_id      => $right_node->id,
   285→        );
   286→        $graph->add_node($cmp);
   287→        return $cmp;
   288→    }
   289→
   290→    method build_less_or_equal_node($left_node, $right_node) {
   291→        my $node_id = $self->next_node_id();
   292→        my $cmp = Chalk::IR::Node::LE->new(
   293→            id            => $node_id,
   294→            inputs        => [$current_control, $left_node->id, $right_node->id],
   295→            left_id       => $left_node->id,
   296→            right_id      => $right_node->id,
   297→        );
   298→        $graph->add_node($cmp);
   299→        return $cmp;
   300→    }
   301→
   302→    method build_not_equal_node($left_node, $right_node) {
   303→        my $node_id = $self->next_node_id();
   304→        my $cmp = Chalk::IR::Node::NE->new(
   305→            id            => $node_id,
   306→            inputs        => [$current_control, $left_node->id, $right_node->id],
   307→            left_id       => $left_node->id,
   308→            right_id      => $right_node->id,
   309→        );
   310→        $graph->add_node($cmp);
   311→        return $cmp;
   312→    }
   313→
   314→    # Control flow nodes
   315→    method build_if_node($condition_node) {
   316→        my $node_id = $self->next_node_id();
   317→        my $if_node = Chalk::IR::Node::If->new(
   318→            id            => $node_id,
   319→            inputs        => [$current_control, $condition_node->id],
   320→            condition_id  => $condition_node->id,
   321→        );
   322→        $graph->add_node($if_node);
   323→        return $if_node;
   324→    }
   325→
   326→    method build_if_true_node($if_node) {
   327→        my $if_true = $self->build_proj_node($if_node, 0, 'IfTrue');
   328→        return $if_true;
   329→    }
   330→
   331→    method build_if_false_node($if_node) {
   332→        my $if_false = $self->build_proj_node($if_node, 1, 'IfFalse');
   333→        return $if_false;
   334→    }
   335→
   336→    method build_region_node(@control_inputs) {
   337→        my $node_id = $self->next_node_id();
   338→        my $region = Chalk::IR::Node::Region->new(
   339→            id            => $node_id,
   340→            inputs        => \@control_inputs,
   341→        );
   342→        $graph->add_node($region);
   343→        return $region;
   344→    }
   345→
   346→    method build_phi_node($region_node, @value_inputs) {
   347→        my $node_id = $self->next_node_id();
   348→        my $phi = Chalk::IR::Node::Phi->new(
   349→            id            => $node_id,
   350→            inputs        => [$region_node->id, @value_inputs],
   351→            region_id     => $region_node->id,
   352→        );
   353→        $graph->add_node($phi);
   354→        return $phi;
   355→    }
   356→
   357→    # Loop control flow nodes
   358→    method build_loop_node($entry_control = undef) {
   359→        my $ctrl = $entry_control // $current_control // '__CONTROL_PLACEHOLDER__';
   360→        my $node_id = $self->next_node_id();
   361→        my $loop = Chalk::IR::Node::Loop->new(
   362→            id            => $node_id,
   363→            inputs        => [$ctrl],  # Entry control; backedge added later
   364→        );
   365→        $graph->add_node($loop);
   366→        return $loop;
   367→    }
   368→
   369→    method build_loop_phi_node($loop_node, $initial_value, $loop_value = undef) {
   370→        # Loop phi starts with control and initial value
   371→        # Loop value added later (lazy phi pattern)
   372→        my @inputs = ($loop_node->id, $initial_value);
   373→        push @inputs, $loop_value if defined $loop_value;
   374→
   375→        my $node_id = $self->next_node_id();
   376→        my $phi = Chalk::IR::Node::Phi->new(
   377→            id            => $node_id,
   378→            inputs        => \@inputs,
   379→            region_id     => $loop_node->id,
   380→        );
   381→        $graph->add_node($phi);
   382→        return $phi;
   383→    }
   384→
   385→    # Function call nodes
   386→    method build_call_node($function_name, @arg_nodes) {
   387→        # Call: control, memory, arguments...
   388→        # For now, use current_control for both control and memory
   389→        my $attributes = { function => $function_name };
   390→        my $node_id = $self->next_node_id();
   391→        my $call = Chalk::IR::Node->new(
   392→            id            => $node_id,
   393→            op            => 'Call',
   394→            inputs        => [$current_control, $current_control, map { $_->id } @arg_nodes],
   395→            attributes    => $attributes,
   396→        );
   397→        $graph->add_node($call);
   398→        return $call;
   399→    }
   400→
   401→    # Loop-carried dependency tracking methods
   402→    method begin_loop_tracking() {
   403→        # Start tracking loop-carried dependencies
   404→        $loop_entry_scope = $scope->snapshot_bindings();
   405→        $loop_tracking_active = 1;
   406→        return;
   407→    }
   408→
   409→    method end_loop_tracking() {
   410→        # End tracking and clean up
   411→        $loop_entry_scope = undef;
   412→        $loop_tracking_active = 0;
   413→        return;
   414→    }
   415→
   416→    method is_tracking_loop() {
   417→        return $loop_tracking_active;
   418→    }
   419→
   420→    method loop_entry_scope() {
   421→        return $loop_entry_scope;
   422→    }
   423→
   424→    method generate_loop_phi_nodes($loop_node) {
   425→        # Generate phi nodes for all variables modified within the loop
   426→        return {} unless $loop_tracking_active;
   427→        return {} unless defined $loop_entry_scope;
   428→
   429→        # Capture current (loop-end) values before creating phis
   430→        my $loop_end_scope = $scope->snapshot_bindings();
   431→
   432→        # Find which variables were modified in the loop
   433→        my @modified_vars = $scope->find_modified_variables($loop_entry_scope);
   434→
   435→        # Generate a phi node for each modified variable
   436→        my %phis = ();
   437→        for my $var (@modified_vars) {
   438→            my $initial_value = $loop_entry_scope->{$var};
   439→            my $loop_value = $loop_end_scope->{$var};
   440→
   441→            # Create phi with initial value; backedge added later
   442→            my $phi = $self->build_loop_phi_node($loop_node, $initial_value, $loop_value);
   443→            $phis{$var} = $phi;
   444→
   445→            # Update scope to use phi node for this variable
   446→            # This ensures uses after the loop see the phi
   447→            $scope->define($var, $phi->id);
   448→        }
   449→
   450→        return \%phis;
   451→    }
   452→
   453→    # Class and object support nodes (Issue #98 Phase 1)
   454→
   455→    method build_classdef_node($class_name, $fields) {
   456→        # Create ClassDef node for class definition
   457→        my $attributes = {
   458→            name => $class_name,
   459→            fields => $fields,
   460→        };
   461→        my $node_id = $self->next_node_id();
   462→        my $classdef = Chalk::IR::Node->new(
   463→            id            => $node_id,
   464→            op            => 'ClassDef',
   465→            inputs        => [$current_control],
   466→            attributes    => $attributes,
   467→        );
   468→        $graph->add_node($classdef);
   469→        return $classdef;
   470→    }
   471→
   472→    method build_new_node($class_name, $field_values_hash) {
   473→        # Create New node for object instantiation
   474→        # $field_values_hash is a hashref mapping field names to node objects
   475→        my @input_nodes = ($current_control);
   476→        my %field_value_refs;
   477→
   478→        # Build field references from hash
   479→        for my $field_name (sort( keys( $field_values_hash->%* ) )) {
   480→            my $value_node = $field_values_hash->{$field_name};
   481→            push @input_nodes, $value_node->id;
   482→            $field_value_refs{$field_name} = {
   483→                op => 'NodeRef',
   484→                node_id => $value_node->id
   485→            };
   486→        }
   487→
   488→        my $attributes = {
   489→            class => $class_name,
   490→            field_values => \%field_value_refs
   491→        };
   492→        my $node_id = $self->next_node_id();
   493→        my $new_obj = Chalk::IR::Node->new(
   494→            id            => $node_id,
   495→            op            => 'New',
   496→            inputs        => \@input_nodes,
   497→            attributes    => $attributes,
   498→        );
   499→        $graph->add_node($new_obj);
   500→        return $new_obj;
   501→    }
   502→
   503→    method build_field_access_node($object_node, $field_name) {
