     1→#!/usr/bin/env perl
     2→# ABOUTME: Tests for low-precedence logical operators (or/and) - issue #45 phase 2
     3→# ABOUTME: These operators are distinct from || and && and commonly used for error handling
     4→
     5→use 5.42.0;
     6→use experimental qw(class);
     7→use utf8;
     8→use Test::More;
     9→use lib 'lib';
    10→use Chalk::Parser;
    11→use Chalk::Grammar::BNF;
    12→use FindBin qw($RealBin);
    13→use File::Spec;
    14→
    15→# Load grammar from BNF file
    16→my $bnf_file = File::Spec->catfile($RealBin, "..", "..", "grammar", "perl.bnf");
    17→open my $grammar_fh, "<:utf8", $bnf_file or die "Cannot open $bnf_file: $!";
    18→my $bnf_content = do { local $/; <$grammar_fh> };
    19→close $grammar_fh;
    20→my $chalk_grammar = Chalk::Grammar->build_from_bnf($bnf_content, "Program");
    21→
    22→
    23→# Create parser
    24→my $parser = Chalk::Parser->new(
    25→    grammar => $chalk_grammar,
    26→    semiring => Chalk::Semiring::Boolean->new(),
    27→);
    28→
    29→# Test basic 'or' operator patterns
    30→subtest 'or operator patterns' => sub {
    31→    ok($parser->parse_string('$x or $y'),
    32→       'Should parse: $x or $y');
    33→
    34→    ok($parser->parse_string('1 or 0'),
    35→       'Should parse: 1 or 0');
    36→
    37→    ok($parser->parse_string('$result = func() or 0'),
    38→       'Should parse: $result = func() or 0');
    39→
    40→    ok($parser->parse_string('return 1 or die'),
    41→       'Should parse: return 1 or die');
    42→};
    43→
    44→# Test basic 'and' operator patterns
    45→subtest 'and operator patterns' => sub {
    46→    ok($parser->parse_string('$x and $y'),
    47→       'Should parse: $x and $y');
    48→
    49→    ok($parser->parse_string('1 and 1'),
    50→       'Should parse: 1 and 1');
    51→
    52→    ok($parser->parse_string('$result = func() and 1'),
    53→       'Should parse: $result = func() and 1');
    54→
    55→    ok($parser->parse_string('$success and print "ok"'),
    56→       'Should parse: $success and print "ok"');
    57→};
    58→
    59→# Test 'or die' pattern - extremely common in Perl
    60→subtest 'or die patterns' => sub {
    61→    ok($parser->parse_string('func() or die'),
    62→       'Should parse: func() or die');
    63→
    64→    ok($parser->parse_string('func() or die "error"'),
    65→       'Should parse: func() or die "error"');
    66→
    67→    ok($parser->parse_string('func() or die "Error: $!"'),
    68→       'Should parse: func() or die "Error: $!"');
    69→
    70→    ok($parser->parse_string('$x = func() or die "failed"'),
    71→       'Should parse: $x = func() or die "failed"');
    72→};
    73→
    74→# Test 'or warn' pattern
    75→subtest 'or warn patterns' => sub {
    76→    ok($parser->parse_string('func() or warn'),
    77→       'Should parse: func() or warn');
    78→
    79→    ok($parser->parse_string('func() or warn "warning"'),
    80→       'Should parse: func() or warn "warning"');
    81→
    82→    ok($parser->parse_string('close $fh or warn "Close failed: $!"'),
    83→       'Should parse: close $fh or warn "Close failed: $!"');
    84→};
    85→
    86→# Test 'and print' pattern
    87→subtest 'and print patterns' => sub {
    88→    ok($parser->parse_string('$success and print "ok"'),
    89→       'Should parse: $success and print "ok"');
    90→
    91→    ok($parser->parse_string('unlink "file" and print "Deleted\n"'),
    92→       'Should parse: unlink "file" and print "Deleted\n"');
    93→};
    94→
    95→# Test patterns from rs.t - the exact failure case
    96→subtest 'rs.t specific patterns' => sub {
    97→    # From rs.t line 13 - this is the actual failure
    98→    ok($parser->parse_string('open TESTFILE, ">./foo" or die "error $! $^E opening"'),
    99→       'Should parse: open TESTFILE, ">./foo" or die "error $! $^E opening"');
   100→
   101→    # From rs.t line 16
   102→    ok($parser->parse_string('close TESTFILE or die "error $! $^E closing"'),
   103→       'Should parse: close TESTFILE or die "error $! $^E closing"');
   104→
   105→    # Simplified versions
   106→    ok($parser->parse_string('open FH, ">file" or die'),
   107→       'Should parse: open FH, ">file" or die');
