#!/usr/bin/env perl
# ABOUTME: Tests for unary operators (!, not, -, +, ++, --) - Issue #109 Phase 1
# ABOUTME: Verifies IR generation for logical and numeric unary operations

use 5.42.0;
use experimental qw(class);
use utf8;
use Test::More;
use lib 'lib';
use Chalk::Parser;
use Chalk::Grammar::BNF;
use FindBin qw($RealBin);
use File::Spec;
use Data::Dumper;

# Load grammar from BNF file
my $bnf_file = File::Spec->catfile($RealBin, "..", "..", "grammar", "perl.bnf");
open my $grammar_fh, "<:utf8", $bnf_file or die "Cannot open $bnf_file: $!";
my $bnf_content = do { local $/; <$grammar_fh> };
close $grammar_fh;
my $chalk_grammar = Chalk::Grammar->build_from_bnf($bnf_content, "Program");

# Create parser
my $parser = Chalk::Parser->new(
    grammar => $chalk_grammar,
    semiring => Chalk::Semiring::Boolean->new(),
);

# Test logical negation with ! operator
subtest 'logical negation with !' => sub {
    my $result = $parser->parse_string('!1');
    ok($result, 'Should parse: !1');

    if ($result && $result->{graph}) {
        my $nodes = $result->{graph}->nodes;
        my $not_nodes = grep { $_->op eq 'Not' } values %$nodes;
        ok($not_nodes > 0, 'Should generate Not node for !1')
            or diag("Graph nodes: " . Dumper($nodes));
    }

    ok($parser->parse_string('!$x'), 'Should parse: !$x');
    ok($parser->parse_string('!($a > $b)'), 'Should parse: !($a > $b)');
};

# Test logical negation with not operator
subtest 'logical negation with not' => sub {
    my $result = $parser->parse_string('not 1');
    ok($result, 'Should parse: not 1');

    if ($result && $result->{graph}) {
        my $nodes = $result->{graph}->nodes;
        my $not_nodes = grep { $_->op eq 'Not' } values %$nodes;
        ok($not_nodes > 0, 'Should generate Not node for not 1')
            or diag("Graph nodes: " . Dumper($nodes));
    }

    ok($parser->parse_string('not $x'), 'Should parse: not $x');
    ok($parser->parse_string('not ($a < $b)'), 'Should parse: not ($a < $b)');
};

# Test numeric negation with - operator
subtest 'numeric negation with -' => sub {
    my $result = $parser->parse_string('-42');
    ok($result, 'Should parse: -42');

    if ($result && $result->{graph}) {
        my $nodes = $result->{graph}->nodes;
        my $negate_nodes = grep { $_->op eq 'Negate' } values %$nodes;
        ok($negate_nodes > 0, 'Should generate Negate node for -42')
            or diag("Graph nodes: " . Dumper($nodes));
    }

    ok($parser->parse_string('-$x'), 'Should parse: -$x');
    ok($parser->parse_string('-($a + $b)'), 'Should parse: -($a + $b)');
    ok($parser->parse_string('--1'), 'Should parse: --1 (double negation)');
};

# Test unary plus (pass-through, should not create node)
subtest 'unary plus (pass-through)' => sub {
    my $result = $parser->parse_string('+42');
    ok($result, 'Should parse: +42');

    # Unary + should NOT create a special node, just pass through
    if ($result && $result->{graph}) {
        my $nodes = $result->{graph}->nodes;
        my $plus_nodes = grep { $_->op eq 'UnaryPlus' } values %$nodes;
        is($plus_nodes, 0, 'Should NOT generate UnaryPlus node (pass-through)');
    }

    ok($parser->parse_string('+$x'), 'Should parse: +$x');
};

# Test double negation (!! or not not)
subtest 'double negation' => sub {
    ok($parser->parse_string('!!$x'), 'Should parse: !!$x');
    ok($parser->parse_string('not not $x'), 'Should parse: not not $x');
    ok($parser->parse_string('!not $x'), 'Should parse: !not $x (mixed)');
};

# Test in conditional contexts
subtest 'unary operators in conditions' => sub {
    ok($parser->parse_string('if (!$flag) { 1 }'),
       'Should parse: if (!$flag) { 1 }');
    ok($parser->parse_string('if (not $flag) { 1 }'),
       'Should parse: if (not $flag) { 1 }');
    ok($parser->parse_string('while (!$done) { 1 }'),
       'Should parse: while (!$done) { 1 }');
};

# Test in expressions
subtest 'unary operators in expressions' => sub {
    ok($parser->parse_string('$result = !$flag'),
       'Should parse: $result = !$flag');
    ok($parser->parse_string('$result = not $flag'),
       'Should parse: $result = not $flag');
    ok($parser->parse_string('$result = -$x'),
       'Should parse: $result = -$x');
    ok($parser->parse_string('$result = !$a + $b'),
       'Should parse: $result = !$a + $b');
};

done_testing();

