        # $module: module name (e.g., '5.42.0', 'experimental', 'Chalk::IR::Node')
        # $imports: arrayref of imported symbols (empty for full import)

        my $graph = $self->graph;
        my $current_control = $self->current_control;

        my $attributes = {
